  ('4dd79956-e501-5359-b24a-04fd8625ae67', null, (select id from public.skills where slug = 'read-g4-authors-purpose'), null, 'easy',
   $q$Which account tells about the discovery from the point of view of someone who found the footprints?$q$, $q$[{"text":"The science article, because it names the state park.","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"Marco's hiking journal, written by one of the two hikers.","is_correct":true},{"text":"The science article, because scientists studied the tracks.","is_correct":false,"misconception_token":"facts-mean-firsthand"},{"text":"Both accounts, because both mention the two young hikers.","is_correct":false,"misconception_token":"same-topic-same-source"}]$q$::jsonb, $q$Marco's hiking journal, written by one of the two hikers.$q$, $q$Marco writes "My sister Lucia and I" and tells how they found the prints, so he is one of the finders. The article only reports that "two young hikers" spotted the tracks.$q$, 'draft', '100dc7b8-ce9d-53d3-87bc-98a28773aa14')
